// src/modules/playback/download/strategies/hifocus.strategy.ts
//
// HiFocus download strategy.
//
// WHY NO NATIVE DOWNLOAD API:
//   HiFocus NVRs expose playback only via ONVIF GetReplayUri (RTSP) and do
//   not provide any documented HTTP file export endpoint in their ONVIF or
//   proprietary API surface. Unlike Hikvision's ISAPI, there is no
//   ContentMgmt/download equivalent. RTSP + ffmpeg is the only option.
//
// This class exists purely for the strategy pattern — it delegates entirely
// to RtspDownloadStrategy. Having a named HiFocus strategy keeps the service
// layer clean (callers don't need to know "HiFocus uses RTSP") and makes it
// easy to add a native API here in the future if HiFocus ever documents one.

import type { NVR } from '@prisma/client'
import type { DownloadContext, DownloadStrategy } from '../types.js'
import logger from '../../../../utils/logger.js'
import { RtspDownloadStrategy } from './rtsp.strategy.js'

export class HifocusDownloadStrategy implements DownloadStrategy {
  readonly name = 'hifocus-rtsp'

  private readonly rtsp = new RtspDownloadStrategy()

  supports(nvr: NVR): boolean {
    return nvr.type === 'HIFOCUS'
  }

  async download(ctx: DownloadContext): Promise<void> {
    logger.info(
      `[${this.name}] HiFocus has no native HTTP download API — using RTSP+ffmpeg. ` +
      `Note: download speed is limited to 1× real-time by the NVR's RTSP playback server.`
    )
    return this.rtsp.download(ctx)
  }
}

// src/modules/playback/download/strategies/hikvision.strategy.ts
//
// Hikvision native download via ISAPI ContentMgmt/download.
//
// WHY THIS IS FAST:
//   The NVR reads the recording file directly from its hard disk and sends the
//   raw bytes over HTTP. No RTSP re-streaming, no real-time playback — just a
//   plain file transfer at full LAN speed. Typically 20–50× faster than the
//   RTSP path for the same clip.
//
// DIGEST AUTH:
//   Hikvision's ISAPI requires HTTP Digest authentication (not Basic).
//   We implement the two-step handshake manually because Node's built-in fetch
//   doesn't do Digest automatically, and adding a dependency just for this is
//   overkill given the simplicity of the algorithm.
//
// FALLBACK:
//   If the NVR returns 404 (firmware doesn't support this endpoint) or any
//   non-2xx code, we throw StrategyUnavailableError and DownloadService will
//   fall back to the RTSP strategy automatically.

import http from 'http'
import crypto from 'crypto'
import type { NVR } from '@prisma/client'
import { StrategyUnavailableError, type DownloadContext, type DownloadStrategy } from '../types.js'
import logger from '../../../../utils/logger.js'

// ── Digest Auth helpers ───────────────────────────────────────────────────────

interface DigestChallenge {
  realm:  string
  nonce:  string
  qop?:   string
  opaque?: string
}

function parseDigestChallenge(wwwAuthenticate: string): DigestChallenge {
  const get = (key: string): string => {
    const m = wwwAuthenticate.match(new RegExp(`${key}="([^"]*)"`, 'i'))
    return m?.[1] ?? ''
  }
  return {
    realm:  get('realm'),
    nonce:  get('nonce'),
    qop:    get('qop') || undefined,
    opaque: get('opaque') || undefined,
  }
}

function buildDigestHeader(
  method: string,
  uri: string,
  username: string,
  password: string,
  challenge: DigestChallenge,
): string {
  const ha1 = crypto.createHash('md5')
    .update(`${username}:${challenge.realm}:${password}`)
    .digest('hex')
  const ha2 = crypto.createHash('md5')
    .update(`${method}:${uri}`)
    .digest('hex')

  let response: string
  let ncHex = ''
  let cnonce = ''

  if (challenge.qop === 'auth') {
    ncHex  = '00000001'
    cnonce = crypto.randomBytes(8).toString('hex')
    response = crypto.createHash('md5')
      .update(`${ha1}:${challenge.nonce}:${ncHex}:${cnonce}:auth:${ha2}`)
      .digest('hex')
  } else {
    response = crypto.createHash('md5')
      .update(`${ha1}:${challenge.nonce}:${ha2}`)
      .digest('hex')
  }

  let header =
    `Digest username="${username}", realm="${challenge.realm}", ` +
    `nonce="${challenge.nonce}", uri="${uri}", response="${response}"`

  if (challenge.qop === 'auth') {
    header += `, qop=auth, nc=${ncHex}, cnonce="${cnonce}"`
  }
  if (challenge.opaque) {
    header += `, opaque="${challenge.opaque}"`
  }

  return header
}

// ── Low-level HTTP helper (node http — no extra deps) ─────────────────────────

function httpGet(
  options: http.RequestOptions,
  onData:  (chunk: Buffer) => boolean,   // return false to abort
  onEnd:   () => void,
  onError: (err: Error) => void,
): http.ClientRequest {
  const req = http.request(options, (res) => {
    res.on('data', (chunk: Buffer) => {
      const ok = onData(chunk)
      if (!ok) req.destroy()
    })
    res.on('end', onEnd)
    res.on('error', onError)
  })
  req.on('error', onError)
  req.setTimeout(30_000, () => req.destroy(new Error('ISAPI request timeout')))
  req.end()
  return req
}

// ── ISAPI download path ───────────────────────────────────────────────────────
// /ISAPI/ContentMgmt/download streams the raw recording file from NVR disk.
// The NVR's RTSP playback server is completely bypassed.

function buildIsapiPath(channel: number, start: Date, end: Date): string {
  const fmt = (d: Date) =>
    d.toISOString().replace(/[-:]/g, '').split('.')[0] + 'Z'
  return (
    `/ISAPI/ContentMgmt/download` +
    `?startTime=${fmt(start)}&endTime=${fmt(end)}&channel=${channel}`
  )
}

// ── Strategy ──────────────────────────────────────────────────────────────────

export class HikvisionDownloadStrategy implements DownloadStrategy {
  readonly name = 'hikvision-isapi'

  supports(nvr: NVR): boolean {
    return nvr.type === 'HIKVISION'
  }

  async download(ctx: DownloadContext): Promise<void> {
    const { nvr, password, channel, start, end, filename, req, res } = ctx
    const path = buildIsapiPath(channel, start, end)

    logger.info(`[${this.name}] starting — ch${channel} ${start.toISOString()}→${end.toISOString()} ${nvr.ip}`)

    // ── Step 1: unauthenticated probe to get the Digest challenge ────────────
    const challenge = await new Promise<DigestChallenge>((resolve, reject) => {
      const probeReq = http.request(
        {
          hostname: nvr.ip,
          port:     nvr.httpPort,
          path,
          method:   'GET',
        },
        (probeRes) => {
          probeRes.resume() // drain body
          if (probeRes.statusCode === 401) {
            const www = probeRes.headers['www-authenticate'] ?? ''
            if (!www.toLowerCase().includes('digest')) {
              // Some older firmware uses Basic auth
              resolve({ realm: '', nonce: '' })
              return
            }
            resolve(parseDigestChallenge(www))
          } else if (probeRes.statusCode === 404) {
            reject(new StrategyUnavailableError(
              `ISAPI ContentMgmt/download not supported on ${nvr.ip} (404) — falling back to RTSP`
            ))
          } else {
            reject(new StrategyUnavailableError(
              `ISAPI probe returned unexpected ${probeRes.statusCode} on ${nvr.ip}`
            ))
          }
        }
      )
      probeReq.setTimeout(10_000, () =>
        probeReq.destroy(new StrategyUnavailableError(`ISAPI probe timed out on ${nvr.ip}`))
      )
      probeReq.on('error', (err) => reject(
        new StrategyUnavailableError(`ISAPI probe network error on ${nvr.ip}: ${err.message}`)
      ))
      probeReq.end()
    })

    // ── Step 2: authenticated request ────────────────────────────────────────
    const authHeader = challenge.nonce
      ? buildDigestHeader('GET', path, nvr.username, password, challenge)
      : 'Basic ' + Buffer.from(`${nvr.username}:${password}`).toString('base64')

    await new Promise<void>((resolve, reject) => {
      let headersSet = false
      let nvrReq: http.ClientRequest

      const cleanup = () => { if (nvrReq) nvrReq.destroy() }
      req.on('close', cleanup) // client cancelled download

      nvrReq = http.request(
        {
          hostname: nvr.ip,
          port:     nvr.httpPort,
          path,
          method:   'GET',
          headers:  { Authorization: authHeader },
        },
        (nvrRes) => {
          if (nvrRes.statusCode === 401) {
            nvrRes.resume()
            return reject(new StrategyUnavailableError(
              `ISAPI auth failed on ${nvr.ip} — check NVR credentials`
            ))
          }
          if (!nvrRes.statusCode || nvrRes.statusCode < 200 || nvrRes.statusCode >= 300) {
            nvrRes.resume()
            return reject(new StrategyUnavailableError(
              `ISAPI returned ${nvrRes.statusCode} on ${nvr.ip} — falling back to RTSP`
            ))
          }

          // Set response headers only once, before any body bytes
          if (!headersSet) {
            headersSet = true
            res.setHeader('Content-Type',        'video/mp4')
            res.setHeader('Content-Disposition', `attachment; filename="${filename}"`)
            res.setHeader('Cache-Control',        'no-cache')

            // Forward Content-Length — enables browser download progress bar
            const cl = nvrRes.headers['content-length']
            if (cl) {
              res.setHeader('Content-Length', cl)
              logger.info(`[${this.name}] Content-Length: ${cl} bytes`)
            }
          }

          // Backpressure-aware pipe: respect res.write() return value so we
          // don't buffer the entire recording in Node's heap if the client
          // is slower than the NVR's disk read speed.
          nvrRes.on('data', (chunk: Buffer) => {
            const ok = res.write(chunk)
            if (!ok) {
              nvrRes.pause()
              res.once('drain', () => nvrRes.resume())
            }
          })

          nvrRes.on('end', () => {
            if (!res.writableEnded) res.end()
            logger.info(`[${this.name}] complete: ${filename}`)
            resolve()
          })

          nvrRes.on('error', (err) => {
            logger.error(`[${this.name}] NVR stream error: ${err.message}`)
            if (!res.writableEnded) res.end()
            reject(err)
          })
        }
      )

      nvrReq.setTimeout(30_000, () => {
        nvrReq.destroy(new Error(`ISAPI download timed out on ${nvr.ip}`))
      })

      nvrReq.on('error', (err) => {
        logger.error(`[${this.name}] request error: ${err.message}`)
        reject(new StrategyUnavailableError(
          `ISAPI network error on ${nvr.ip}: ${err.message}`
        ))
      })

      nvrReq.end()
    })
  }
}

// src/modules/playback/download/strategies/rtsp.strategy.ts
//
// RTSP + ffmpeg download strategy.
//
// WHY RTSP IS SLOW FOR DOWNLOADS:
//   The NVR's RTSP playback server replays footage at 1× real-time speed —
//   a 1-hour clip takes ~1 hour to transfer regardless of network bandwidth.
//   This is a protocol constraint of RTSP, not a code problem. Native HTTP
//   file download APIs (like Hikvision ISAPI) bypass this entirely.
//
// WHEN THIS IS USED:
//   - HiFocus NVRs (no documented native HTTP download API)
//   - Hikvision fallback (if ISAPI endpoint returns 404 on older firmware)
//
// FFMPEG FLAGS FOR DOWNLOAD (different from streaming):
//   - NO frag_keyframe+empty_moov: those flags are for low-latency streaming.
//     For a download we want a single well-formed MP4 the user can seek in
//     after saving — that requires a complete moov atom.
//   - faststart: moves the moov atom to the front of the file so the
//     browser/VLC can start seeking immediately after download completes.
//   - -t durationSec: hard stop prevents ffmpeg from running forever if the
//     NVR serves more data than requested (some firmware quirks).
//   - SIGTERM before SIGKILL: lets ffmpeg send RTSP TEARDOWN to the NVR so
//     the slot is released immediately rather than timing out after ~60s.

import { spawn } from 'child_process'
import type { NVR } from '@prisma/client'
import { generatePlaybackRTSP } from '../../playback.generator.js'
import { getHifocusReplayInfo } from '../../hifocus.replay.js'
import { activeStreams, streamKey } from '../../playback.stream.js'
import { env } from '../../../../config/env.js'
import logger from '../../../../utils/logger.js'
import type { DownloadContext, DownloadStrategy } from '../types.js'

export class RtspDownloadStrategy implements DownloadStrategy {
  readonly name = 'rtsp-ffmpeg'

  // Accepts any NVR — this is the universal fallback
  supports(_nvr: NVR): boolean {
    return true
  }

  async download(ctx: DownloadContext): Promise<void> {
    const { nvr, password, channel, start, end, filename, req, res } = ctx

    const durationSec = Math.round((end.getTime() - start.getTime()) / 1000)

    logger.info(
      `[${this.name}] starting — ${nvr.type} ch${channel} ` +
      `${start.toISOString()}→${end.toISOString()} (${durationSec}s)`
    )

    // ── Build RTSP URL ────────────────────────────────────────────────────────
    let rtspUrl: string
    if (nvr.type === 'HIKVISION') {
      rtspUrl = generatePlaybackRTSP(
        { username: nvr.username, password, ip: nvr.ip, rtspPort: nvr.rtspPort, type: 'HIKVISION' },
        channel, start, end,
      )
    } else if (nvr.type === 'HIFOCUS') {
      const info = await getHifocusReplayInfo(
        nvr.ip, nvr.httpPort, nvr.rtspPort,
        nvr.username, password,
        channel, start, end,
      )
      rtspUrl = info.rtspUrl
    } else {
      throw new Error(`Unsupported NVR type: ${nvr.type}`)
    }

    // ── Kill any active playback stream on this channel first ─────────────────
    // HiFocus (and some Hikvision firmware) reject a second concurrent RTSP
    // connection on the same channel with 453 "Not Enough Bandwidth".
    const key = streamKey(nvr.id, channel)
    const existingPlayback = activeStreams.get(key)
    if (existingPlayback) {
      logger.info(`[${this.name}] killing active playback stream for ${key} before download`)
      existingPlayback.kill()
      await new Promise((r) => setTimeout(r, env.PLAYBACK_NVR_SLOT_RELEASE_MS))
    }

    // ── Spawn ffmpeg ──────────────────────────────────────────────────────────
    const ffmpeg = spawn('ffmpeg', [
  '-loglevel',       'warning',
  '-rtsp_transport', 'tcp',
  '-timeout',        '10000000',
  '-i',              rtspUrl,
  '-t',              String(durationSec),
  '-c:v',            'copy',
  '-an',
  // faststart needs a seekable output; pipe:1 isn't seekable, so fragment
  // instead — no seek-back required, still playable/seekable downstream.
  '-movflags',       'frag_keyframe+empty_moov+default_base_moof',
  '-f',              'mp4',
  'pipe:1',
    ])

    const killFfmpeg = () => {
      ffmpeg.kill('SIGTERM')
      setTimeout(() => {
        if (ffmpeg.exitCode === null && ffmpeg.signalCode === null) {
          ffmpeg.kill('SIGKILL')
        }
      }, 2_000)
    }

    req.on('close', () => {
      logger.info(`[${this.name}] client cancelled: ${filename}`)
      killFfmpeg()
    })

    // ── Set headers before any bytes flow ────────────────────────────────────
    res.setHeader('Content-Type',        'video/mp4')
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`)
    res.setHeader('Cache-Control',       'no-cache')
    // No Content-Length — we don't know the encoded size until ffmpeg finishes

    ffmpeg.stdout.pipe(res)

    ffmpeg.stderr.on('data', (data: Buffer) => {
      const redacted = data.toString().trim().replace(/rtsp:\/\/[^@]+@/g, 'rtsp://***:***@')
      logger.debug(`[${this.name}:ffmpeg] ${redacted}`)
    })

    await new Promise<void>((resolve, reject) => {
      ffmpeg.on('close', (code) => {
        if (code !== 0 && code !== null) {
          logger.warn(`[${this.name}] ffmpeg exited ${code} for ${filename}`)
        } else {
          logger.info(`[${this.name}] complete: ${filename}`)
        }
        if (!res.writableEnded) res.end()
        resolve()
      })

      ffmpeg.on('error', (err) => {
        logger.error(`[${this.name}] ffmpeg spawn error: ${err.message}`)
        if (!res.headersSent) {
          res.status(500).json({ error: 'ffmpeg failed to start.' })
        } else {
          res.end()
        }
        reject(err)
      })
    })
  }
}

