import axios from "axios";
import { XMLParser } from "fast-xml-parser";
import { env } from "../../config/env.js";
import { withRetry } from "../../utils/retry.js";
import logger from "../../utils/logger.js";

export interface RecordingSegment {
  startTime: Date;
  endTime: Date;
  channel: number;
}

const parser = new XMLParser({
  ignoreAttributes: false,
  parseTagValue: true,
});

const PAGE_SIZE = 100;

// Build the ISAPI search XML body
const buildSearchXML = (
  channel: number,
  startTime: Date,
  endTime: Date,
  searchResultPosition: number
): string => {
  const trackID = channel * 100 + 1
  const start = startTime.toISOString().split('.')[0] + 'Z'
  const end = endTime.toISOString().split('.')[0] + 'Z'

  return `<?xml version="1.0" encoding="utf-8"?><CMSearchDescription><searchID>CBB5C492-9FA0-0001-90CF-6A02B5D417F9</searchID><trackList><trackID>${trackID}</trackID></trackList><timeSpanList><timeSpan><startTime>${start}</startTime><endTime>${end}</endTime></timeSpan></timeSpanList><maxResults>${PAGE_SIZE}</maxResults><searchResultPostion>${searchResultPosition}</searchResultPostion><metadataList><metadataDescriptor>//recordType.meta.std-cgi.com</metadataDescriptor></metadataList></CMSearchDescription>`
}

// A single ISAPI search page. Read-only + idempotent, so bounded retry on
// network/5xx failures is safe (Phase 4) — auth/4xx failures are NOT retried,
// since retrying the same bad credentials wastes the NVR's request budget
// and will never succeed.
const searchPage = async (
  url: string,
  username: string,
  password: string,
  channel: number,
  startTime: Date,
  endTime: Date,
  searchResultPosition: number
): Promise<{ items: any[]; isEnd: boolean; numOfMatches: number }> => {
  const xmlBody = buildSearchXML(channel, startTime, endTime, searchResultPosition);
  logger.debug(`Hikvision search page: pos=${searchResultPosition} ch=${channel}`);

  const responseData = await withRetry(
    async () => {
      try {
        const response = await axios.post<string>(url, xmlBody, {
          auth: { username, password },
          headers: { "Content-Type": "application/xml" },
          responseType: "text",
          timeout: 15000,
          transformRequest: [(data) => data], // prevent axios from touching the body
        });
        return response.data;
      } catch (err) {
        if (axios.isAxiosError(err) && err.response) {
          logger.error(`Hikvision search raw response: ${err.response.data}`);
          // 4xx (auth/bad request) — not retry-worthy, rethrow a tagged error.
          if (err.response.status >= 400 && err.response.status < 500) {
            const nonRetryable = new Error(`Hikvision search rejected (HTTP ${err.response.status})`);
            (nonRetryable as any).nonRetryable = true;
            throw nonRetryable;
          }
        }
        throw err;
      }
    },
    {
      retries: env.PLAYBACK_SEARCH_RETRIES,
      baseDelayMs: 500,
      isRetryable: (err) => !(err as any)?.nonRetryable,
      label: `Hikvision search (${channel}, pos=${searchResultPosition})`,
    }
  );

  const parsed = parser.parse(responseData);
  const result = parsed?.CMSearchResult;
  const matchList = result?.matchList?.searchMatchItem;
  const items = matchList ? (Array.isArray(matchList) ? matchList : [matchList]) : [];
  const numOfMatches = Number(result?.numOfMatches ?? items.length);
  const responseStatus = result?.responseStatus;
  // ISAPI signals no-more-results either via responseStatusStrg or by
  // returning fewer than a full page — treat either as the end.
  const isEnd = responseStatus === false || responseStatus === 'false' || items.length < PAGE_SIZE;

  return { items, isEnd, numOfMatches };
};

export const searchHikvisionRecordings = async (
  ip: string,
  httpPort: number,
  username: string,
  password: string,
  channel: number,
  startTime: Date,
  endTime: Date,
): Promise<RecordingSegment[]> => {
  const url = `http://${ip}:${httpPort}/ISAPI/ContentMgmt/search`;

  const allItems: any[] = [];
  let position = 0;

  // Loop until the NVR signals no more results — closes the silent-
  // truncation gap where a >100-result day would previously be cut off
  // without warning (Phase 4).
  // Bounded to a generous number of pages as a safety valve against a
  // misbehaving NVR that never reports isEnd.
  for (let page = 0; page < 50; page++) {
    const { items, isEnd } = await searchPage(url, username, password, channel, startTime, endTime, position);
    allItems.push(...items);
    if (isEnd || items.length === 0) break;
    position += PAGE_SIZE;
  }

  if (allItems.length >= PAGE_SIZE * 50) {
    logger.warn(`Hikvision search for ch${channel} hit the pagination safety cap — results may be incomplete.`);
  }

  return allItems
    .map((item: { timeSpan?: { startTime?: string; endTime?: string } }) => {
      const start = item?.timeSpan?.startTime;
      const end = item?.timeSpan?.endTime;
      if (!start || !end) return null;
      return {
        channel,
        startTime: new Date(start),
        endTime: new Date(end),
      };
    })
    .filter((s): s is RecordingSegment => s !== null);
};

import prisma from '../../config/db.js'
import { decrypt } from '../../utils/crypto.js'
import { discoverHikvisionCameras } from './hikvision.discoverer.js'
import { discoverHifocusCameras } from './hifocus.discoverer.js'
import type { DiscoveredCamera } from './hikvision.discoverer.js'
import logger from '../../utils/logger.js'
import {
  emitNvrStatus,
  emitCameraStatus,
  emitCameraNew,
} from '../../services/socketService.js'

export const runDetectionForNVR = async (nvrId: string): Promise<void> => {
  // 1 — Fetch NVR from DB with credentials
  const nvr = await prisma.nVR.findUnique({
    where: { id: nvrId },
    include: { cameras: true },
  })

  if (!nvr) {
    logger.warn(`Detection skipped — NVR ${nvrId} not found in DB`)
    return
  }

  const decryptedPassword = decrypt(nvr.password)

  // 2 — Poll NVR for connected cameras
  let discovered: DiscoveredCamera[] | null = []
  let nvrReachable = true

  try {
    if (nvr.type === 'HIKVISION') {
      discovered = await discoverHikvisionCameras(
        nvr.ip,
        nvr.httpPort,
        nvr.username,
        decryptedPassword
      )
    } else {
      discovered = await discoverHifocusCameras(
        nvr.ip,
        nvr.httpPort,
        nvr.username,
        decryptedPassword
      )
    }
  } catch (err) {
    nvrReachable = false
    logger.warn(`NVR ${nvr.name} (${nvr.ip}) unreachable: ${String(err)}`)
  }

  // 3 — Update NVR status + emit Socket.io event
  const updatedNvr = await updateNVRStatus(nvrId, nvrReachable, nvr.offlineSince)
  emitNvrStatus({
    nvrId,
    status: updatedNvr.status as 'ONLINE' | 'OFFLINE',
    lastSeenAt: updatedNvr.lastSeenAt,
    offlineSince: updatedNvr.offlineSince,
  })

  if (!nvrReachable) return

  // 4 — Reconcile discovered cameras with DB
  if (discovered !== null) {
    await reconcileCameras(nvrId, discovered, nvr.cameras)
  }
}

// ─── NVR Status ──────────────────────────────────────────

const updateNVRStatus = async (
  nvrId: string,
  isReachable: boolean,
  currentOfflineSince: Date | null
) => {
  if (isReachable) {
    return prisma.nVR.update({
      where: { id: nvrId },
      data: {
        status: 'ONLINE',
        lastSeenAt: new Date(),
        offlineSince: null,
      },
      select: { status: true, lastSeenAt: true, offlineSince: true },
    })
  } else {
    const [updatedNvr] = await prisma.$transaction([
      prisma.nVR.update({
        where: { id: nvrId },
        data: {
          status: 'OFFLINE',
          offlineSince: currentOfflineSince ?? new Date(),
        },
        select: { status: true, lastSeenAt: true, offlineSince: true },
      }),
      // When the NVR is unreachable, all its cameras are effectively offline too.
      // Mark them all so the frontend never shows a camera as online under an offline NVR.
      prisma.camera.updateMany({
        where: {
          nvrId,
          isOnline: true, // only touch cameras that are currently marked online
        },
        data: {
          isOnline: false,
          offlineSince: new Date(),
        },
      }),
    ])

    return updatedNvr
  }
}
// ─── Camera Reconciliation ───────────────────────────────

const reconcileCameras = async (
  nvrId: string,
  discovered: DiscoveredCamera[],
  existingCameras: {
    id: string
    channel: number
    isOnline: boolean
    offlineSince: Date | null
  }[]
): Promise<void> => {
  const discoveredMap = new Map(discovered.map((c) => [c.channel, c]))
  const existingMap = new Map(existingCameras.map((c) => [c.channel, c]))

  const now = new Date()

  // Process each discovered camera
  for (const [channel, discoveredCam] of discoveredMap) {
    const existing = existingMap.get(channel)

    if (!existing) {
      // New camera — insert into DB and notify frontend
      const newCamera = await prisma.camera.create({
        data: {
          nvrId,
          channel,
          name: `Channel ${channel}`,
          isActive: true,
          isOnline: discoveredCam.isOnline,
          lastSeenAt: discoveredCam.isOnline ? now : null,
          offlineSince: discoveredCam.isOnline ? null : now,
          protocol: discoveredCam.protocol ?? null,
        },
      })

      logger.info(`New camera discovered on NVR ${nvrId} — channel ${channel}`)

      emitCameraNew({
        camera: {
          id: newCamera.id,
          nvrId,
          channel,
          name: newCamera.name,
          isOnline: newCamera.isOnline,
        },
      })
      continue
    }

    // Existing camera — update status only
    const goingOffline = !discoveredCam.isOnline && existing.isOnline
    const comingOnline = discoveredCam.isOnline && !existing.isOnline

    const updatedCamera = await prisma.camera.update({
      where: { id: existing.id },
      data: {
        isOnline: discoveredCam.isOnline,
        lastSeenAt: discoveredCam.isOnline ? now : undefined,
        offlineSince: comingOnline
          ? null
          : goingOffline
          ? now
          : existing.offlineSince,
        protocol: discoveredCam.protocol ?? undefined,
      },
      select: { id: true, isOnline: true, offlineSince: true },
    })

    // Only emit when status actually changed — avoids noisy frontend updates
    if (goingOffline || comingOnline) {
      emitCameraStatus({
        cameraId: existing.id,
        nvrId,
        channel,
        isOnline: updatedCamera.isOnline,
        offlineSince: updatedCamera.offlineSince,
      })
    }
  }

  // Mark cameras not in discovery response as offline
  for (const [channel, existing] of existingMap) {
    if (!discoveredMap.has(channel) && existing.isOnline) {
      await prisma.camera.update({
        where: { id: existing.id },
        data: {
          isOnline: false,
          offlineSince: existing.offlineSince ?? now,
        },
      })

      logger.info(`Camera channel ${channel} on NVR ${nvrId} went offline`)

      emitCameraStatus({
        cameraId: existing.id,
        nvrId,
        channel,
        isOnline: false,
        offlineSince: existing.offlineSince ?? now,
      })
    }
  }
}

